awk 'BEGIN{
  while ((getline line < "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") > 0) {
    s = line;
    for (i = 1; i <= length(s); i++) {
      if (substr(s,i,3) == "8XD") {
        rest = substr(s, i+3);
        n = 0;
        while (n < length(rest) && rest ~ /^[A-Z0-9]/) { n++; rest = substr(rest,2); }
        # rebuild
        cand = substr(s, i, n+3);
        if (n >= 17 && substr(cand, length(cand)-2) == "W54" && n+3 == 23) print "MATCH", cand;
      }
    }
  }
}'
